#!/usr/bin/env bash
# Second half of the auto-fix job: commit whatever the agent rewrote onto a
# fresh branch and open a pull request against the branch that broke.
set -euo pipefail

if [[ -z "$(git status --porcelain -- src)" ]]; then
  echo "open-fix-pr: nothing under src/ changed; no pull request to open." >&2
  exit 1
fi

git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'

git checkout -b "${FIX_BRANCH}"
git add -- src
git commit -m "fix: repair the failing reservation build

Generated by the auto-fix job of run ${GITHUB_RUN_ID}. The patch was produced
from the Jest failure log; only files under src/ were in scope."
git push origin "${FIX_BRANCH}"

if [[ "${VERIFY_OUTCOME}" == "success" ]]; then
  verdict='Lint, typecheck and the full Jest suite all pass on the patched tree.'
else
  verdict='The re-run of lint, typecheck or the Jest suite still fails. Do not merge without a manual fix.'
fi

{
  cat auto-heal-report.md
  cat <<BODY

### Automated verification

${verdict}

The agent may only write files under \`src/\`, and the runner refuses any path
under \`src/test/\` or a \`__tests__/\` directory. The diff below therefore
cannot contain a relaxed assertion.

- Failing run: ${GITHUB_SERVER_URL}/${GITHUB_REPOSITORY}/actions/runs/${GITHUB_RUN_ID}
- Base branch: \`${BASE_BRANCH}\`

### Audit log — human-in-the-loop review

_To be completed by the reviewer before this patch is accepted._

- [ ] The diff touches source code only; no test file, assertion or threshold was changed.
- [ ] The change addresses the cause named in the diagnosis, not just the symptom in the log.
- [ ] No validation, error handling or contract behaviour was dropped to make the suite green.
- [ ] The restored behaviour matches the OpenAPI contract in \`docs/openapi.yaml\`.
BODY
} > pr-body.md

gh pr create \
  --base "${BASE_BRANCH}" \
  --head "${FIX_BRANCH}" \
  --title "fix: auto-healed build from run ${GITHUB_RUN_ID}" \
  --body-file pr-body.md
